param([Parameter(Mandatory=$true)][string]$SourcePath,[Parameter(Mandatory=$true)][string]$HeaderPath,[Parameter(Mandatory=$true)][string]$TestPath,[Parameter(Mandatory=$true)][string]$CoreCMakePath,[Parameter(Mandatory=$true)][string]$TestsCMakePath,[Parameter(Mandatory=$true)][string]$ForbiddenPaths)
$ErrorActionPreference='Stop';$s=Get-Content -Raw $SourcePath;$h=Get-Content -Raw $HeaderPath;$hn=(($h -replace '\r?\n\s*\*\s*',' ') -replace '\s+',' ');$t=Get-Content -Raw $TestPath;$c=Get-Content -Raw $CoreCMakePath;$tc=Get-Content -Raw $TestsCMakePath
function A([bool]$x,[string]$m){if(-not$x){throw $m}}
function O([string]$x,[string[]]$v){$i=0;foreach($n in $v){$j=$x.IndexOf($n,$i,[StringComparison]::Ordinal);if($j-lt 0){return $false};$i=$j+$n.Length};return $true}
function V([string]$x){(O $x @('static int Preflight(','Separate(identity, sizeof(*identity), platform','Separate(identity, sizeof(*identity), report','Separate(platform, sizeof(*platform), report','*identity_snapshot = *identity','*platform_snapshot = *platform','AcquireLease == NULL','AdoptExisting == NULL','RollbackBookkeeping == NULL','ReleaseLease == NULL','Separate(report, sizeof(*report),')) -and (O $x @('Preflight(identity, platform, report','AcquireAttempted = 1','AcquireLease(','AcquireStatus != 0','VMX_EPT_RUNTIME_ADOPTION_ACQUIRE_FAILED','LeaseHeld = 1','VmxEptRuntimeRootPlanBuild(','PlanStatus != VMX_EPT_RUNTIME_ROOT_PLAN_OK','VMX_EPT_RUNTIME_ADOPTION_PLAN_FAILED','PlanValid = 1','AdoptAttempted = 1','AdoptExisting(','published != 0','published == 1','VMX_EPT_RUNTIME_ADOPTION_ADOPT_FAILED','published != 0','RollbackAttempted = 1','RollbackBookkeeping(','RootAdopted = 0','VMX_EPT_RUNTIME_ADOPTION_ROLLBACK_FAILED','ReleaseAttempted = 1','ReleaseLease(','LeaseHeld = 0','VMX_EPT_RUNTIME_ADOPTION_RELEASE_FAILED','*report = staged'))}
A(V $s)'transaction ordering';foreach($v in @('WDK-free','allocation-free','externally serialized','without native','releases exactly once','MUST NOT','VMXOFF','Release failure has precedence','Preflight failure preserves','pairwise separate','No pinning','IRQL change','VMX/EPT instruction','hook','IOCTL','driver binding')){A($hn.Contains($v))"header $v"}
foreach($v in @('preflight preserves','no second VMXON','multi-group identity','acquire','plan','unpublished','published rollback','rollback fail','conservative adopted','release precedence','lease retained','success without publication','release overrides plan failure','prior plan status retained','release overrides adopt failure','prior adopt status retained')){A($t.Contains($v))"test $v"}
A((([regex]::Matches($c,'(?m)^\s*vmx_ept_runtime_adoption_coordinator\.c\r?$')).Count-eq 1))'core source once';A((([regex]::Matches($tc,'add_executable\(test_vmx_ept_runtime_adoption_coordinator')).Count-eq 1))'test once'
A($s-notmatch 'ntddk|wdm\.h|wdf|__vmx|__invept|VmxOn\s*\(|VmxOff\s*\(|INVEPT|KeSet|KeRaise|IOCTL|Hook|DriverOwner')'forbidden dependency';foreach($p in $ForbiddenPaths.Split(',')){A((Get-Content -Raw $p)-notmatch 'VmxEptCoordinateRuntimeRootAdoption|vmx_ept_runtime_adoption_coordinator')"unwired $p"}
$m=@($s.Replace('Separate(report, sizeof(*report),','Bypass(report, sizeof(*report),'),$s.Replace('staged.AcquireStatus != 0','staged.AcquireStatus == 0'),$s.Replace('VmxEptRuntimeRootPlanBuild(&proof, &staged.Plan)','VMX_EPT_RUNTIME_ROOT_PLAN_OK'),$s.Replace('published == 1','published == 0'),$s.Replace('published != 0) {','published == 0) {'),$s.Replace('callbacks.RollbackBookkeeping(','callbacks.AdoptExisting('),$s.Replace('staged.RootAdopted = 0;','staged.RootAdopted = 1;'),$s.Replace('callbacks.ReleaseLease(','callbacks.AcquireLease('),$s.Replace('result = VMX_EPT_RUNTIME_ADOPTION_RELEASE_FAILED;','result = VMX_EPT_RUNTIME_ADOPTION_OK;'),$s.Replace('*report = staged;','memset(report,0,sizeof(*report));'))
for($i=0;$i-lt$m.Count;$i++){A($m[$i]-ne$s)"mutation missing $i";A(-not(V $m[$i]))"accepted mutation $i"}
Write-Host 'PASS: persistent root adoption transaction contracts'
